// GENERATED by scripts/tokens/build_plugin.py from design/figma/tokens-bridge.js — do not edit.

// Coco tokens ⇄ Figma variables and text styles.
//
// Plain Figma Plugin API JavaScript, shared by:
//   • design/figma/plugin (a development plugin you run inside Figma), and
//   • the Figma MCP `use_figma` tool (paste this file, then call one of the functions).
//
//   await importTokens(tokens)  — create or update collections, variables and text styles
//                                 from a design/tokens.json object. Never deletes anything;
//                                 returns what it changed and what Figma has that the JSON doesn't.
//   await exportTokens()        — read Figma back into the design/tokens.json shape.
//
// Naming: a token's key is its Figma variable (or text style) name. The Swift name travels as
// the variable's iOS code syntax ("Theme.paper", "Space.xl") or, for text styles, the
// description line "Swift: TypeStyle.bodySmall".

const COCO_GROUPS = {
  // group key in tokens.json → Swift type used in iOS code syntax and default scopes
  color: { swiftType: 'Theme', kind: 'COLOR' },
  brand: { swiftType: 'BrandPalette', kind: 'COLOR', scopes: ['FRAME_FILL', 'SHAPE_FILL', 'STROKE_COLOR'] },
  space: { swiftType: 'Space', kind: 'FLOAT', scopes: ['GAP'] },
  radius: { swiftType: 'Radius', kind: 'FLOAT', scopes: ['CORNER_RADIUS'] },
  metrics: { swiftType: 'Metrics', kind: 'FLOAT' },
};
const COCO_WEIGHTS = {
  // tokens.json weight → Figma style name per family key
  sans: { light: 'Light', regular: 'Regular', medium: 'Medium', semibold: 'Semi Bold', bold: 'Bold', heavy: 'Extra Bold' },
  mono: { light: 'Light', regular: 'Regular', medium: 'Medium', semibold: 'SemiBold', bold: 'Bold' },
};

function cocoHexToRgb(hex) {
  const c = hex.replace('#', '');
  return { r: parseInt(c.slice(0, 2), 16) / 255, g: parseInt(c.slice(2, 4), 16) / 255, b: parseInt(c.slice(4, 6), 16) / 255, a: 1 };
}
function cocoRgbToHex({ r, g, b }) {
  const h = v => Math.round(v * 255).toString(16).padStart(2, '0').toUpperCase();
  return '#' + h(r) + h(g) + h(b);
}
function cocoRound(n) {
  return Math.round(n * 10000) / 10000;
}
function cocoEntries(group) {
  return Object.entries(group || {}).filter(([k]) => !k.startsWith('$'));
}
// Figma hands descriptions back HTML-escaped ("Coco&#39;s").
function cocoUnescape(text) {
  return String(text || '').replace(/&#39;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}
// FNV-1a over the UTF-16 code units of the compact JSON; scripts/tokens/apply_figma_export.py checks it.
function cocoChecksum(text) {
  let hash = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}

async function importTokens(tokens) {
  const report = { collections: [], created: [], updated: [], textStyles: [], extrasInFigma: [] };
  const existing = await figma.variables.getLocalVariableCollectionsAsync();
  const allVars = await figma.variables.getLocalVariablesAsync();

  async function collection(name, modeNames) {
    let c = existing.find(x => x.name === name);
    if (!c) {
      c = figma.variables.createVariableCollection(name);
      existing.push(c);
      report.collections.push(name);
    }
    c.renameMode(c.modes[0].modeId, modeNames[0]);
    for (const modeName of modeNames.slice(1)) {
      if (!c.modes.find(m => m.name === modeName)) c.addMode(modeName);
    }
    return c;
  }
  function variable(c, name, type) {
    let v = allVars.find(x => x.variableCollectionId === c.id && x.name === name);
    if (!v) {
      v = figma.variables.createVariable(name, c, type);
      allVars.push(v);
      report.created.push(`${c.name}/${name}`);
    } else {
      report.updated.push(`${c.name}/${name}`);
    }
    return v;
  }

  // Primitives: raw colors, hidden from pickers.
  const prim = await collection(tokens.primitives.$collection, ['Value']);
  const primByName = {};
  for (const [name, hex] of cocoEntries(tokens.primitives)) {
    const v = variable(prim, name, 'COLOR');
    v.setValueForMode(prim.modes[0].modeId, cocoHexToRgb(hex));
    v.scopes = [];
    primByName[name] = v;
  }
  const colorValue = ref => (primByName[ref] ? figma.variables.createVariableAlias(primByName[ref]) : cocoHexToRgb(ref));

  for (const [group, spec] of Object.entries(COCO_GROUPS)) {
    const source = tokens[group];
    const modes = source.$modes || ['Value'];
    const c = await collection(source.$collection, modes);
    const seen = new Set();
    for (const [name, token] of cocoEntries(source)) {
      const v = variable(c, name, spec.kind);
      seen.add(name);
      if (spec.kind === 'COLOR' && source.$modes) {
        modes.forEach(m => v.setValueForMode(c.modes.find(x => x.name === m).modeId, colorValue(token[m.toLowerCase()])));
      } else if (spec.kind === 'COLOR') {
        v.setValueForMode(c.modes[0].modeId, colorValue(token.value));
      } else {
        // Figma measures opacity variables in percent; the code (and tokens.json) uses 0–1.
        const percent = (token.scopes || []).includes('OPACITY');
        v.setValueForMode(c.modes[0].modeId, percent ? token.value * 100 : token.value);
      }
      v.scopes = token.scopes || spec.scopes || [];
      v.description = token.description || '';
      v.setVariableCodeSyntax('iOS', `${spec.swiftType}.${token.swift}`);
    }
    for (const v of allVars.filter(x => x.variableCollectionId === c.id && !seen.has(x.name))) {
      report.extrasInFigma.push(`${c.name}/${v.name}`);
    }
  }

  // Fonts as STRING variables, so the family behind each key is visible and editable.
  const type = await collection('Type', ['Value']);
  for (const [key, font] of Object.entries(tokens.fonts)) {
    const v = variable(type, `font/${key}`, 'STRING');
    v.setValueForMode(type.modes[0].modeId, font.figma);
    v.scopes = ['FONT_FAMILY'];
    v.description = font.description || '';
    v.setVariableCodeSyntax('iOS', `Font.Design.${font.swift}`);
  }

  // Text styles.
  const styles = await figma.getLocalTextStylesAsync();
  for (const [name, t] of cocoEntries(tokens.typography)) {
    const fontName = { family: tokens.fonts[t.family].figma, style: COCO_WEIGHTS[t.family][t.weight] };
    await figma.loadFontAsync(fontName);
    let s = styles.find(x => x.name === name);
    if (!s) {
      s = figma.createTextStyle();
      s.name = name;
      styles.push(s);
      report.textStyles.push(`created ${name}`);
    } else {
      report.textStyles.push(`updated ${name}`);
    }
    s.fontName = fontName;
    s.fontSize = t.size;
    s.letterSpacing = { unit: 'PIXELS', value: t.tracking || 0 };
    s.lineHeight = { unit: 'AUTO' };
    s.textCase = t.uppercase ? 'UPPER' : 'ORIGINAL';
    s.description = `Swift: TypeStyle.${t.swift}`;
  }
  for (const s of styles) {
    if (!tokens.typography[s.name]) report.extrasInFigma.push(`text style ${s.name}`);
  }
  return report;
}

async function exportTokens() {
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const allVars = await figma.variables.getLocalVariablesAsync();
  const byId = Object.fromEntries(allVars.map(v => [v.id, v]));
  const warnings = [];
  const varsIn = c => c.variableIds.map(id => byId[id]).filter(Boolean);
  const find = name => collections.find(c => c.name === name);

  const out = {
    $description: "Coco design tokens: the one source for the Swift code and the Figma variables and text styles. Edit in Figma and sync (docs/DESIGN_SYSTEM.md), or edit here and push to Figma. Keys are Figma names; `swift` is the Swift identifier.",
    $version: 1,
  };

  const prim = find('Primitives');
  if (!prim) throw new Error('No “Primitives” collection');
  out.primitives = { $collection: 'Primitives' };
  for (const v of varsIn(prim)) out.primitives[v.name] = cocoRgbToHex(v.valuesByMode[prim.modes[0].modeId]);
  const primName = id => (byId[id] && byId[id].variableCollectionId === prim.id ? byId[id].name : null);
  const colorRef = (value, where) => {
    if (value && value.type === 'VARIABLE_ALIAS') {
      const name = primName(value.id);
      if (name) return name;
      warnings.push(`${where} aliases a non-primitive variable; exported its resolved value`);
      return cocoRgbToHex(byId[value.id].valuesByMode[Object.keys(byId[value.id].valuesByMode)[0]]);
    }
    return cocoRgbToHex(value);
  };
  const swiftName = (v, swiftType) => {
    const syntax = (v.codeSyntax && v.codeSyntax.iOS) || '';
    if (syntax.startsWith(swiftType + '.')) return syntax.slice(swiftType.length + 1);
    const derived = v.name.split(/[\/\- ]+/).map((p, i) => (i ? p[0].toUpperCase() + p.slice(1) : p)).join('');
    warnings.push(`${v.name}: no iOS code syntax; using Swift name “${derived}”`);
    return derived;
  };

  const groupFor = { Color: 'color', Brand: 'brand', Space: 'space', Radius: 'radius', Metrics: 'metrics' };
  for (const [collectionName, group] of Object.entries(groupFor)) {
    const c = find(collectionName);
    if (!c) throw new Error(`No “${collectionName}” collection`);
    const spec = COCO_GROUPS[group];
    const section = { $collection: collectionName };
    if (group === 'color') section.$modes = c.modes.map(m => m.name);
    for (const v of varsIn(c)) {
      const token = { swift: swiftName(v, spec.swiftType) };
      if (group === 'color') {
        for (const m of c.modes) token[m.name.toLowerCase()] = colorRef(v.valuesByMode[m.modeId], v.name);
      } else if (spec.kind === 'COLOR') {
        token.value = colorRef(v.valuesByMode[c.modes[0].modeId], v.name);
      } else {
        const raw = v.valuesByMode[c.modes[0].modeId];
        token.value = cocoRound(v.scopes.includes('OPACITY') ? raw / 100 : raw);
      }
      const sameAsDefault = JSON.stringify(v.scopes) === JSON.stringify(spec.scopes || []);
      if (group === 'color' || group === 'metrics' || !sameAsDefault) token.scopes = v.scopes;
      if (v.description) token.description = cocoUnescape(v.description);
      section[v.name] = token;
    }
    out[group] = section;
  }

  const type = find('Type');
  const fontVar = key => type && varsIn(type).find(v => v.name === `font/${key}`);
  out.fonts = {};
  for (const [key, swift] of [['sans', 'default'], ['mono', 'monospaced']]) {
    const v = fontVar(key);
    if (!v) throw new Error(`No “font/${key}” variable in the Type collection`);
    out.fonts[key] = { figma: v.valuesByMode[type.modes[0].modeId], swift };
    if (v.description) out.fonts[key].description = cocoUnescape(v.description);
  }

  out.typography = {};
  const familyKey = family => Object.keys(out.fonts).find(k => out.fonts[k].figma === family);
  for (const s of await figma.getLocalTextStylesAsync()) {
    const family = familyKey(s.fontName.family);
    if (!family) {
      warnings.push(`text style ${s.name}: font ${s.fontName.family} isn't font/sans or font/mono; skipped`);
      continue;
    }
    const plain = s.fontName.style.toLowerCase().replace(/\s+/g, '');
    const weight = { extrabold: 'heavy', ultrabold: 'heavy' }[plain] || plain;
    const match = /Swift: TypeStyle\.(\w+)/.exec(s.description || '');
    const swift = match ? match[1] : s.name.split(/[\/ ]+/).map((p, i) => (i ? p[0].toUpperCase() + p.slice(1) : p.toLowerCase())).join('');
    if (!match) warnings.push(`text style ${s.name}: no “Swift: TypeStyle.…” in its description; using “${swift}”`);
    const style = { swift, family, weight, size: cocoRound(s.fontSize) };
    const tracking = s.letterSpacing.unit === 'PIXELS' ? cocoRound(s.letterSpacing.value) : cocoRound((s.letterSpacing.value / 100) * s.fontSize);
    if (tracking) style.tracking = tracking;
    if (s.textCase === 'UPPER') style.uppercase = true;
    out.typography[s.name] = style;
  }
  return { tokens: out, warnings, checksum: cocoChecksum(JSON.stringify(out)) };
}

// --- Plugin entry point -------------------------------------------------------
figma.showUI(__html__, { width: 440, height: 400, themeColors: true });
figma.ui.onmessage = async msg => {
  try {
    if (msg.type === 'export') {
      figma.ui.postMessage({ type: 'exported', result: await exportTokens() });
    } else if (msg.type === 'import') {
      const parsed = JSON.parse(msg.json);
      figma.ui.postMessage({ type: 'imported', report: await importTokens(parsed.tokens || parsed) });
    }
  } catch (error) {
    figma.ui.postMessage({ type: 'error', message: String((error && error.message) || error) });
  }
};
